const hive=document.querySelector('#hive'),modal=document.querySelector('#modal'),portrait=document.querySelector('#portrait'),quote=document.querySelector('#quote'),modalName=document.querySelector('#modalName'),counter=document.querySelector('#counter'),sourceLink=document.querySelector('#sourceLink');let current=0,touchX=0;
people.forEach((p,i)=>{const b=document.createElement('button');b.className='person';b.style.setProperty('--duration',`${4.8+(i%5)*.55}s`);b.style.setProperty('--delay',`${-(i*.37)}s`);b.setAttribute('aria-label',`פתיחת הציטוט של ${p.name}`);b.innerHTML=`<img src="assets/people/${p.image}" alt="" loading="lazy" style="object-position:${p.position||'50% 38%'}"><span class="person-name">${p.name}</span>`;b.addEventListener('click',()=>open(i));hive.appendChild(b)});
function render(){const p=people[current];portrait.style.backgroundImage=`url("assets/people/${p.image}")`;portrait.style.backgroundPosition=p.position||'50% 38%';quote.textContent=p.quote;modalName.textContent=p.name;counter.textContent=`${current+1} / ${people.length}`;sourceLink.href=p.source}function open(i){current=i;render();modal.hidden=false;document.body.style.overflow='hidden';document.querySelector('.close').focus()}function close(){modal.hidden=true;document.body.style.overflow='';document.querySelectorAll('.person')[current].focus()}function move(step){current=(current+step+people.length)%people.length;render()}
document.querySelectorAll('[data-close]').forEach(x=>x.addEventListener('click',close));document.querySelector('.next').addEventListener('click',()=>move(1));document.querySelector('.prev').addEventListener('click',()=>move(-1));document.addEventListener('keydown',e=>{if(modal.hidden)return;if(e.key==='Escape')close();if(e.key==='ArrowRight')move(-1);if(e.key==='ArrowLeft')move(1)});modal.addEventListener('touchstart',e=>touchX=e.changedTouches[0].clientX,{passive:true});modal.addEventListener('touchend',e=>{const d=e.changedTouches[0].clientX-touchX;if(Math.abs(d)>55)move(d>0?-1:1)},{passive:true});

// Apple Watch-style free-moving hive: drag, pinch, wheel zoom and center emphasis.
const viewport=document.querySelector('#hiveViewport'),buttons=[...document.querySelectorAll('.person')];
const view={x:0,y:0,zoom:1,min:.62,max:1.65};
const activePointers=new Map();let dragStart=null,dragMoved=false,pinchStart=null,raf=0;
const spacing=116,rowHeight=100;
const cols=5,totalRows=Math.ceil(people.length/cols);const coords=people.map((_,i)=>{const row=Math.floor(i/cols),col=i%cols,rowCount=Math.min(cols,people.length-row*cols);return{x:(col-(rowCount-1)/2)*spacing+(row%2?spacing/2:0),y:(row-(totalRows-1)/2)*rowHeight}});
function clamp(n,a,b){return Math.max(a,Math.min(b,n))}
const contentHalfW=Math.max(...coords.map(c=>Math.abs(c.x)))+spacing/2,contentHalfH=Math.max(...coords.map(c=>Math.abs(c.y)))+rowHeight/2;
function constrainView(){const r=viewport.getBoundingClientRect(),maxX=Math.max(36,contentHalfW-r.width/(2*view.zoom)+spacing*1.15),maxY=Math.max(36,contentHalfH-r.height/(2*view.zoom)+rowHeight*1.15);view.x=clamp(view.x,-maxX,maxX);view.y=clamp(view.y,-maxY,maxY)}
function renderHive(time=0){constrainView();const r=viewport.getBoundingClientRect(),cx=r.width/2,cy=r.height/2,base=matchMedia('(max-width:620px)').matches?78:92;buttons.forEach((b,i)=>{const c=coords[i],phase=i*1.73;const fx=Math.sin(time/1600+phase)*3,fy=Math.cos(time/1800+phase)*4;const sx=cx+(c.x+view.x)*view.zoom+fx,sy=cy+(c.y+view.y)*view.zoom+fy;const d=Math.hypot(sx-cx,sy-cy),focus=clamp(1.22-d/900,.72,1.16),scale=view.zoom*focus;b.style.left=`${sx}px`;b.style.top=`${sy}px`;b.style.transform=`translate(-50%,-50%) scale(${scale})`;b.style.opacity=String(clamp(1-d/900,.45,1));b.style.zIndex=String(Math.round(focus*100))});raf=requestAnimationFrame(renderHive)}
function setZoom(next,anchorX,anchorY){const r=viewport.getBoundingClientRect(),cx=r.width/2,cy=r.height/2,old=view.zoom,z=clamp(next,view.min,view.max);if(anchorX!=null){const ax=anchorX-r.left-cx,ay=anchorY-r.top-cy;view.x-=ax/z-ax/old;view.y-=ay/z-ay/old}view.zoom=z;constrainView()}
function resetHive(){view.x=0;view.y=0;view.zoom=1}
viewport.addEventListener('pointerdown',e=>{if(e.target.closest('.zoom-controls'))return;viewport.setPointerCapture(e.pointerId);activePointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(activePointers.size===1){dragStart={px:e.clientX,py:e.clientY,x:view.x,y:view.y};dragMoved=false}else if(activePointers.size===2){const p=[...activePointers.values()];pinchStart={distance:Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y),zoom:view.zoom}}});
viewport.addEventListener('pointermove',e=>{if(!activePointers.has(e.pointerId))return;activePointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(activePointers.size===2&&pinchStart){const p=[...activePointers.values()],distance=Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y),mx=(p[0].x+p[1].x)/2,my=(p[0].y+p[1].y)/2;setZoom(pinchStart.zoom*distance/pinchStart.distance,mx,my);dragMoved=true}else if(activePointers.size===1&&dragStart){const dx=e.clientX-dragStart.px,dy=e.clientY-dragStart.py;if(Math.hypot(dx,dy)>5)dragMoved=true;view.x=dragStart.x+dx/view.zoom;view.y=dragStart.y+dy/view.zoom}});
function endPointer(e){activePointers.delete(e.pointerId);pinchStart=null;if(activePointers.size===1){const p=[...activePointers.values()][0];dragStart={px:p.x,py:p.y,x:view.x,y:view.y}}else dragStart=null}
viewport.addEventListener('pointerup',endPointer);viewport.addEventListener('pointercancel',endPointer);viewport.addEventListener('click',e=>{if(dragMoved){e.preventDefault();e.stopImmediatePropagation();dragMoved=false}},true);
viewport.addEventListener('wheel',e=>{e.preventDefault();setZoom(view.zoom*Math.exp(-e.deltaY*.0012),e.clientX,e.clientY)},{passive:false});
document.querySelector('#zoomIn').addEventListener('click',()=>setZoom(view.zoom*1.18));document.querySelector('#zoomOut').addEventListener('click',()=>setZoom(view.zoom/1.18));document.querySelector('#resetView').addEventListener('click',resetHive);window.addEventListener('resize',resetHive);raf=requestAnimationFrame(renderHive);
